const DEFAULT_STYLES=[{id:'ilustratie',name:'Ilustrație',type:'char',italic:true},{id:'accent',name:'Accent',type:'char',bold:true},{id:'sanscrit',name:'Termen sanscrit',type:'char',italic:true},{id:'citat-bloc',name:'Citat bloc',type:'para',italic:true,indent:2},{id:'motto',name:'Motto',type:'para',italic:true,align:'right',size:90},{id:'scrisoare',name:'Scrisoare',type:'para',indent:1.5,size:95},{id:'centrat',name:'Centrat',type:'para',align:'center'},{id:'separator',name:'Separator de scenă',type:'para',align:'center',spacing:1}];
