const rx = s => new RegExp(s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'));
const esc = s => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
async function range(H, text, occurrence=0, caret=false) {
  await H.editor().click();
  const ok=await H.editor().evaluate((el,{text,occurrence,caret})=>{
    const w=document.createTreeWalker(el,NodeFilter.SHOW_TEXT),nodes=[];let n,whole='';
    while((n=w.nextNode())){nodes.push({n,start:whole.length});whole+=n.textContent}
    let at=-1;for(let i=0;i<=occurrence;i++)at=whole.indexOf(text,at+1);if(at<0)return false;
    const find=p=>{for(const x of nodes)if(p>=x.start&&p<=x.start+x.n.length)return [x.n,p-x.start];return null};
    const a=find(at+(caret?Math.min(2,text.length):0)),b=find(caret?at+Math.min(2,text.length):at+text.length);if(!a||!b)return false;
    const r=document.createRange();r.setStart(...a);r.setEnd(...b);const s=getSelection();s.removeAllRanges();s.addRange(r);document.dispatchEvent(new Event('selectionchange'));return true;
  },{text,occurrence,caret});
  H.assert(ok,'Fixture selection not found: '+text);await H.sleep(100);
}
const selection=H=>H.p.evaluate(()=>String(getSelection()));
const view=H=>H.p.evaluate(()=>JSON.parse(localStorage.getItem('pneuma-editor-view')||'{}'));
const settings=H=>H.p.evaluate(()=>window.api.getSettings());
async function saved(H, predicate, message='Specific saved HTML not observed') {await H.save();await H.wait(()=>predicate(H.doc()),7000);H.assert(predicate(H.doc()),message)}
async function attr(H, selector, name, value) {await H.wait(async()=>await H.editor().locator(selector).first().getAttribute(name)===String(value));await saved(H,h=>h.includes(`${name}="${esc(value)}"`))}
async function group(H,id){let q=H.p.locator(`.format-bar .fb-group[data-i="${ALL.indexOf(id)}"]`);if(!await q.count()){await H.p.locator('.format-bar .fb-more > button').click();await H.wait(async()=>await q.count()>0)}return q}
async function pop(H,id){const q=await group(H,id);await q.locator('.menu > button').first().click();await H.wait(async()=>await q.locator('.menu-pop').count()>0);await H.shot(H.currentCase+'-dropdown');return q.locator('.menu-pop').last()}
async function pick(H,id,label){const q=await pop(H,id);const item=q.locator('button').filter({hasText:typeof label==='string'?rx(label):label});H.assert(await item.count()===1,'Ambiguous/missing item '+id+' '+label);await item.click()}
async function button(H,id,label){await (await group(H,id)).getByRole('button',{name:label,exact:true}).click()}
async function prompt(H,value,cancel=false){const q=H.p.locator('.prompt-modal');await q.waitFor();await H.shot(H.currentCase+'-prompt');if(cancel)await q.getByRole('button',{name:'Anulează',exact:true}).click();else{await q.locator('input').fill(String(value));await q.locator('button[type="submit"]').click()}}
async function seed(H,html=BASE,mutate){await H.fixture(async(p,f)=>{f['docs/doc-a.html']=html;if(mutate)await mutate(p,f)});}
async function fullbar(H){await H.settingsFixture({toolbars:{format:ALL,seen:{format:ALL}}})}
async function close(H,selector='.modal'){const q=H.p.locator(selector).last();await q.getByRole('button',{name:/^(Închide|Anulează)$/}).first().click()}
async function contextOpen(H){
  // Observe the actual Menu built by setupSpelling. Preserve popup behavior; no substituted menu.
  await H.app.evaluate(({Menu})=>{if(!global.__qaEditorPopupObserver){const original=Menu.prototype.popup;Menu.prototype.popup=function(options){global.__qaEditorPopup=this;return original.call(this,options)};global.__qaEditorPopupObserver=true}global.__qaEditorPopup=null});
  await H.editor().click({button:'right'});await H.wait(()=>H.app.evaluate(()=>Boolean(global.__qaEditorPopup)));
}
async function contextItems(H){return H.app.evaluate(()=>{const walk=(xs,r=[])=>xs.filter(x=>x.type!=='separator').flatMap(x=>[{route:[...r,x.label],role:x.role,enabled:x.enabled},...(x.submenu?walk(x.submenu.items,[...r,x.label]):[])]);return walk(global.__qaEditorPopup?.items||[])})}
async function contextClick(H,route){const result=await H.app.evaluate(({BrowserWindow},{route,wid})=>{let m=global.__qaEditorPopup,item;for(const label of route){item=m?.items.find(x=>x.label===label);if(!item)return false;m=item.submenu}if(!item.enabled)return false;global.__qaEditorPopup.closePopup();item.click(undefined,BrowserWindow.fromId(wid));return true},{route,wid:H.windowId});H.assert(result,'Native context route unavailable '+route.join(' > '));await H.sleep(120)}
async function clipboard(H,text,html){await H.app.evaluate(({clipboard},{text,html})=>{clipboard.clear();clipboard.write({text,...(html?{html}:{})})},{text,html})}
const clip=H=>H.app.evaluate(({clipboard})=>clipboard.readText());
async function nativeId(H,id){const ms=await H.menu(),m=ms.find(m=>m.commandId===id&&!m.submenu);H.assert(m,'Canonical native command missing '+id);await H.native(m.route)}
function tableHTML(merged=false){return '<table><tbody>'+Array.from({length:3},(_,r)=>'<tr>'+Array.from({length:3},(_,c)=>r===0&&merged&&c===1?'':`<td${r===0&&merged&&c===0?' colspan="2"':''}><p>R${r}C${c}</p></td>`).join('')+'</tr>').join('')+'</tbody></table><p>Tail</p>'}
const imageHTML='<p>Before</p><img src="'+PNG+'" alt="QA image" width="64"><p>After</p>';
